'use strict';

// MODULES //

var map = require( '@stdlib/array/base/map' );
var symbol2shape = require( '@stdlib/plot/base/symbol2shape' );


// MAIN //

/**
* Converts an array of symbol aliases and/or shorthands to Vega symbol mark shapes.
*
* ## Notes
*
* -   If unable to resolve a shape for an element of the input array, the corresponding element in the output array is `null`.
*
* @param {Collection<string>} symbols - symbol aliases and/or shorthands
* @returns {Array} symbol mark shapes
*
* @example
* var v = symbols2shapes( [ 'o', 'square' ] );
* // returns [ 'circle', 'square' ]
*
* v = symbols2shapes( [ 'o', 'beep' ] );
* // returns [ 'circle', null ]
*/
function symbols2shapes( symbols ) {
	return map( symbols, symbol2shape );
}


// EXPORTS //

module.exports = symbols2shapes;
